import React, { useState } from "react";

export default function ApplyForm() {
  const [formData, setFormData] = useState({
    vendorName: "",
    ownerName: "",
    email: "",
    phone: "",
    operatingRegion: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:8080/addVendor", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error("Failed to submit");
      }

      alert("Vendor added successfully!");
      setFormData({
        vendorName: "",
        ownerName: "",
        email: "",
        phone: "",
        operatingRegion: ""
      });
    } catch (error) {
      console.error("Error submitting form", error);
      alert("Error submitting form");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="p-4">
      <input name="vendorName" value={formData.vendorName} onChange={handleChange} placeholder="Vendor Name" />
      <input name="ownerName" value={formData.ownerName} onChange={handleChange} placeholder="Owner Name" />
      <input name="email" value={formData.email} onChange={handleChange} placeholder="Email" />
      <input name="phone" value={formData.phone} onChange={handleChange} placeholder="Phone" />
      <input name="operatingRegion" value={formData.operatingRegion} onChange={handleChange} placeholder="Operating Region" />
      <button type="submit">Submit</button>
    </form>
  );
}
